人が呼吸すれば二酸化炭素が増え、ガスを燃やせば一酸化炭素や水蒸気が出ます。これらが一定の濃さを超えると健康被害が出るので、その濃さを超えないだけの新鮮空気を送り込む必要があります。その量が必要換気量です。ポイントは「汚染物質の発生量」と「許容濃度」の2つだけで決まるという点です。式は1本しかありません。

