同じ大きさのスピーカーを2台にしても、音の大きさは2倍には聞こえません。せいぜい「少し大きくなった」程度です。これは人の耳が音の強さを対数（何桁分か）で感じるためで、その感覚に合わせた単位がデシベルです。デシベルは倍率を表す単位なので、単純に足すことはできません。ここさえ理解すれば、音の計算問題はパターンが3つしかないことが分かります。

━━━━━━━━━━━━━━━━━━━━━━
