・つり合い条件式は3つ
　水平方向の力の総和＝0
　鉛直方向の力の総和＝0
　任意点まわりのモーメントの総和＝0★
・したがって未知反力が3つまでなら解ける＝静定

━━━━━━━━━━━━━━━━━━━━━━
