×「積雪の単位荷重は1cmあたり10N/m²である」→誤り。20N/m²以上
×「地震層せん断力係数は下層ほど大きい」→誤り。上層ほど大きい（Ai）
×「速度圧は基準風速に比例する」→誤り。2乗に比例
×「Rtは建物の固有周期が長いほど大きい」→誤り。小さくなる
○「柱・基礎の積載荷重は支える階数が多いほど低減できる」→正しい

