・接合部のせん断耐力は、柱せい・梁幅・コンクリート強度で決まる
・接合部の形状による分類：十字形＞ト形＞L形の順にせん断耐力が高い★
・柱梁接合部内では、梁主筋を通し配筋するのが原則
