　工法｜信頼性｜下地の動きへの追従｜適する部位｜
　アスファルト（保護）｜最も高い★｜低い｜陸屋根・駐車場｜
　シート（塩ビ）｜高い｜中｜広い陸屋根・改修★｜
　ウレタン塗膜｜中｜高い★｜複雑形状・バルコニー★｜
　FRP塗膜｜中｜低い｜木造バルコニー★｜
