建物の外壁には必ず目地があります。部材どうしの間に隙間を設けておかないと、温度変化や地震で部材が動いたときに互いをこじって壊してしまうからです。しかし隙間があれば水が入ります。そこで、動きに追従しながら水を止める弾性のある材料が必要になります。これがシーリング材です。「どれだけ動くか」と「相手の材料は何か」の2つで種類が決まります。

━━━━━━━━━━━━━━━━━━━━━━
