・塗装間隔（工程間隔時間）を守る。短すぎると縮み、長すぎると付着不良
・塗膜の厚さは、単位面積あたりの使用量（kg/m²）で管理する★
・仕上塗材（吹付けタイル等）は、下塗り・主材・上塗りの3層構成

